package edu.seu.vcampus.common.course; import java.io.*; import java.time.*; import java.util.Objects;
/** Creates a complete academic-term window configuration. */ public record CreateTermCommand(String termCode,String termName,LocalDate startDate,LocalDate endDate,Instant enrollmentStartAt,Instant enrollmentEndAt,Instant adjustmentStartAt,Instant adjustmentEndAt,String termStatus) implements Serializable{@Serial private static final long serialVersionUID=1L;public CreateTermCommand{Objects.requireNonNull(termCode);Objects.requireNonNull(termName);Objects.requireNonNull(startDate);Objects.requireNonNull(endDate);Objects.requireNonNull(enrollmentStartAt);Objects.requireNonNull(enrollmentEndAt);Objects.requireNonNull(adjustmentStartAt);Objects.requireNonNull(adjustmentEndAt);Objects.requireNonNull(termStatus);CourseValidation.text("termCode",termCode,24);CourseValidation.text("termName",termName,64);if(!endDate.isAfter(startDate)||!enrollmentEndAt.isAfter(enrollmentStartAt)||!adjustmentStartAt.isAfter(enrollmentEndAt)||!adjustmentEndAt.isAfter(adjustmentStartAt)||!SetHolder.STATUSES.contains(termStatus))throw new IllegalArgumentException("invalid term");}private static final class SetHolder{static final java.util.Set<String> STATUSES=java.util.Set.of("PLANNED","ACTIVE","CLOSED");}}
